public Object dialog(DialogRunbase dialog = null, boolean forceOnClient = false)
{
    FormBuildStringControl codeControl;
    Dialog                 ret;

    ret = this.dialogInternal(dialog, forceOnClient);

    ret.caption("@UnifiedPricingService:UPSPriceAttributeGroupHierarchyView");

    dfPriceComponentCodeName = ret.addField(extendedTypeStr(UPSPriceComponentCodeName),
                                            "@UnifiedPricingService:UPSPriceComponentCode");

    return ret;
}

public boolean validate(Object _calledFrom = null)
{
    boolean ret = super(_calledFrom);

    var priceComponentCodeName = dfPriceComponentCodeName.value();

    if (!UPSPriceComponentCode::findName(dfPriceComponentCodeName.value()).RecId)
    {
        ret = checkFailed(strFmt("@UnifiedPricingService:UPSPriceComponentCodeNotExist", priceComponentCodeName));
    }

    return ret;
}

public static void main(Args _args)
{
    var hierarchyView = UPSPriceAttributeGroupPriorityHierarchyView::construct();

    if (hierarchyView.prompt())
    {
        UPSPriceComponentCode rec = UPSPriceComponentCode::findName(hierarchyView.dfPriceComponentCodeName.value());

        FormRun formRun = classfactory.formRunClass(new Args(formstr(UPSPriceAttributeGroupPriorityHierarchyView)));
        formRun.args().record(rec);
        formRun.run();
        formRun.wait();
    }

}
